---BEGIN BASIC EXAMPLE---
export default async function (context) {
  return {
    status: 200,
    body: 'Hello, world!',
    headers: {
      'Access-Control-Allow-Origin': 'https://graphql-server.com',
    },
  };
};
---END BASIC EXAMPLE---

The "context" argument is following this interface below called "LambdaContext"

interface LambdaContext {
  request: {
    path: string;
    query: string;
    method: string;
    body: unknown;
    headers: Headers
  };
  response: Response;
  getSecret<T = Record<string, string>>(secret: string): Promise<T>;
  getConfig(secret: string): Promise<Record<string, string>>;
  getLambdaInfo(): {
    name: string;
    namespace: string;
    resourceVersion: string;
    uid: string;
  };
  getQueryParams(): Record<string, string>;
  getBodyParams(): Record<string, string>;
  getRouteParams(): Record<string, string>;
}


---BEGIN GRAPHQL EXAMPLE---
import {
  Bootstrap,
  Container,
  Controller,
  CoreModule,
  GraphQLInt,
  GraphQLNonNull,
  GraphQLObjectType,
  HAPI_SERVER,
  Module,
  Query,
  Type,
} from '@gapi/core';
import { lastValueFrom, tap } from 'rxjs';
import { format } from 'url';

export interface Context {
  request: {
    url: string;
    query: string;
    method: string;
    body: unknown;
    headers: Headers;
  };
  response: Response;
  getSecret<T = Record<string, string>>(secret: string): Promise<T>;
  getConfig(secret: string): Promise<Record<string, string>>;
  getLambdaInfo(): {
    name: string;
    namespace: string;
    resourceVersion: string;
    uid: string;
  };
  getQueryParams(): Record<string, string>;
  getBodyParams(): Record<string, string>;
  getRouteParams(): Record<string, string>;
}

export const UserType = new GraphQLObjectType({
  name: 'UserType',
  fields: () => ({
    id: {
      type: GraphQLInt,
    },
  }),
});

@Controller()
export class UserQueriesController {
  @Type(UserType)
  @Query({
    id: {
      type: new GraphQLNonNull(GraphQLInt),
    },
  })
  findUser(root, { id }, context) {
    return { id: id };
  }
}

@Module({
  imports: [
    CoreModule.forRoot({
      server: {
        hapi: {
          port: 9000,
          routes: {
            cors: {
              origin: ['*'],
              additionalHeaders: [
                'Host',
                'User-Agent',
                'Accept',
                'Accept-Language',
                'Accept-Encoding',
                'Access-Control-Request-Method',
                'Access-Control-Allow-Origin',
                'Access-Control-Request-Headers',
                'Origin',
                'Connection',
                'Pragma',
                'cardId',
                'Cache-Control',
              ],
            },
          },
        },
      },
      graphql: {
        path: '/graphql',
        initQuery: true,
        openBrowser: false,
        graphqlOptions: {
          tracing: false,
          schema: null,
        },
      },
    }),
  ],
  controllers: [UserQueriesController],
})
export class AppModule {}

const Main = lastValueFrom(
  Bootstrap(AppModule).pipe(
    tap(() => {
      console.log('[Bootstrap]: Started');
    }),
  ),
);

export default async function handler(context: Context) {
  const request = context.request;
  const headers = {
    'Content-type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'DELETE,GET,HEAD,OPTIONS,PATCH,POST,PUT',
  };
  await Main;

  const url = format({
    pathname: '/graphql',
    query: request.query,
  });
  const options = {
    method: request.method,
    url,
    payload: request.body,
    headers: request.headers,
    validate: false,
  };
  let res = {
    statusCode: 502,
    result: null,
  };
  console.log('Request Options: ', options);
  try {
    res = await Container.get(HAPI_SERVER).inject(options);
  } catch (e) {
    console.error('ERROR', JSON.stringify(e));
  }
  return {
    status: res.statusCode,
    body: res.result,
    headers,
  };
}
---END GRAPHQL EXAMPLE---
IMPORTANT: Always install "@gapi/core": "^1.8.184" inside package.json when graphql example is asked tell the user what you are going to do!!
